"""SRS 10 Nov UC017: My Request filters, Department Request (Head of Department), All Request (Assistant / Head of Admin)."""
import sys, re
from lib import *
reseed()
s1 = user('stf001'); hos = user('hos001'); hos2 = user('hos002'); ad = user('admin'); hd = user('head001'); drv = user('drv001')
cnt = lambda q: int(sql(q))
mine = cnt("SELECT COUNT(*) FROM vehicle_requests WHERE staff_id=(SELECT user_id FROM users WHERE username='stf001')")
r = s1.get('staff/my_requests.php'); ok('My Request lists the own requests with vehicle type', r.status_code == 200 and not errs(r) and mine > 0 and r.text.count('<details') == mine)
st = sql("SELECT status FROM vehicle_requests WHERE staff_id=(SELECT user_id FROM users WHERE username='stf001') LIMIT 1")
r = s1.get('staff/my_requests.php', status=st); n = cnt("SELECT COUNT(*) FROM vehicle_requests WHERE status='%s' AND staff_id=(SELECT user_id FROM users WHERE username='stf001')" % st)
ok('filter by status', r.text.count('<details') == n)
r = s1.get('staff/my_requests.php', **{'from': '2099-01-01'}); ok('2.1: no request matches -> "No record is found"', 'No record is found' in r.text and r.text.count('<details') == 0)
r = s1.get('staff/my_requests.php', **{'from': '2000-01-01', 'to': '2099-01-01'}); ok('filter by date range keeps the requests', r.text.count('<details') == mine)
r = s1.get('staff/my_requests.php', status="x'; DROP TABLE users;--"); ok('a bad filter value is ignored', r.status_code == 200 and cnt("SELECT COUNT(*) FROM users") > 0)
dept = sql("SELECT department FROM users WHERE username='hos001'")
dn = cnt("SELECT COUNT(*) FROM vehicle_requests vr JOIN users u ON u.user_id=vr.staff_id WHERE u.department='%s'" % dept)
r = hos.get('supervisor/department_requests.php'); ok('A1: the Head of Department sees the requests of the department (any status)', r.status_code == 200 and r.text.count('<details') == dn and not errs(r))
other = cnt("SELECT COUNT(*) FROM vehicle_requests vr JOIN users u ON u.user_id=vr.staff_id WHERE u.department<>'%s'" % dept)
ok('and only that department (others exist)', other > 0 and r.text.count('<details') < dn + other)
r = hos.get('supervisor/department_requests.php', status='zzz'); ok('department list ignores a bad status', r.status_code == 200)
r = s1.get('supervisor/department_requests.php'); ok('staff cannot open Department Request (role check)', r.status_code in (302, 403))
r = ad.get('admin/vehicle_requests.php', tab='all'); total = cnt("SELECT COUNT(*) FROM vehicle_requests")
ok('A2: All Request shows every department', r.status_code == 200 and r.text.count('<details') == total and 'All Request' in r.text and not errs(r))
r = ad.get('admin/vehicle_requests.php', tab='all', department=dept); k = cnt("SELECT COUNT(*) FROM vehicle_requests vr JOIN users u ON u.user_id=vr.staff_id WHERE u.department='%s'" % dept)
ok('All Request filters by department', r.text.count('<details') == k and k < total)
r = hd.get('admin/vehicle_requests.php', tab='all', status='pending'); ok('the Head of Admin filters by status', r.text.count('<details') == cnt("SELECT COUNT(*) FROM vehicle_requests WHERE status='pending'"))
r = ad.get('admin/vehicle_requests.php', tab='all', **{'from': '2099-01-01'}); ok('All Request: nothing matches -> "No record is found"', 'No record is found' in r.text)
sys.exit(0 if summary() else 1)
